//! Optional private-network publication for Remote AI Studio.
//!
//! The Remote AI Studio gateway itself stays loopback-only. This module owns
//! optional machine-local adapters that publish that loopback endpoint to an
//! authenticated private network without making any overlay vendor part of the
//! gateway, Agent Host, ACP, or MCP contracts.

use crate::remote_ai_studio::normalized_phone_url_base;
use serde::{Deserialize, Serialize};
use serde_json::Value;
use std::fs;
use std::io;
use std::path::PathBuf;
use std::process::Command;
use std::sync::mpsc;
use std::thread;

const STATE_SCHEMA_VERSION: u32 = 1;
const TAILSCALE_HTTPS_PORT: u16 = 443;

/// Which private-network publication path the user selected on this machine.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, Default)]
#[serde(rename_all = "snake_case")]
pub(crate) enum RemotePublicationMode {
    /// A user-owned HTTPS reverse proxy supplies the external origin.
    #[default]
    Manual,
    /// GameEngine reconciles one explicitly opted-in Tailscale Serve mapping.
    TailscaleServe,
}

impl RemotePublicationMode {
    pub(crate) const fn label(self) -> &'static str {
        match self {
            Self::Manual => "Manual private network",
            Self::TailscaleServe => "Tailscale Serve",
        }
    }
}

/// A Tailscale Serve mapping that GameEngine previously created successfully.
///
/// Ownership is intentionally narrow: GameEngine may update a mapping after a
/// gateway port change only when Tailscale still reports the exact previous
/// loopback target recorded here. A different existing mapping is unmanaged and
/// is never overwritten or removed.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub(crate) struct ManagedTailscalePublication {
    origin: String,
    gateway_endpoint: String,
}

impl ManagedTailscalePublication {
    pub(crate) fn origin(&self) -> &str {
        &self.origin
    }

    fn gateway_endpoint(&self) -> &str {
        &self.gateway_endpoint
    }
}

#[derive(Debug, Serialize, Deserialize)]
struct PersistedRemotePublication {
    schema_version: u32,
    #[serde(default)]
    mode: RemotePublicationMode,
    #[serde(default)]
    tailscale: Option<ManagedTailscalePublication>,
}

impl Default for PersistedRemotePublication {
    fn default() -> Self {
        Self {
            schema_version: STATE_SCHEMA_VERSION,
            mode: RemotePublicationMode::Manual,
            tailscale: None,
        }
    }
}

/// User-facing state of the optional Tailscale publication adapter.
#[derive(Debug, Clone, PartialEq, Eq, Default)]
pub(crate) enum TailscalePublicationState {
    /// The user has not asked GameEngine to manage Tailscale Serve yet.
    #[default]
    SetupRequired,
    /// A local CLI probe or reconciliation is running off the UI thread.
    Checking,
    /// Tailscale is not installed or its CLI cannot be found.
    NotInstalled,
    /// Tailscale is installed but the local node is not connected.
    Disconnected,
    /// Windows rejected Serve because the current process is not elevated.
    AdministratorRequired,
    /// The installed CLI does not expose the machine-readable contract used here.
    UnsupportedCli,
    /// HTTPS 443 already has an unmanaged Serve or Funnel configuration.
    ExistingConfigurationConflict,
    /// Tailscale reported another safe-to-display setup failure.
    Failed,
    /// The private HTTPS origin is published to the current loopback gateway.
    Ready {
        /// Origin that may be combined with the Remote AI Studio access token.
        origin: String,
    },
}

impl TailscalePublicationState {
    pub(crate) const fn label(&self) -> &'static str {
        match self {
            Self::SetupRequired => "Setup required",
            Self::Checking => "Checking",
            Self::NotInstalled => "Not installed",
            Self::Disconnected => "Not connected",
            Self::AdministratorRequired => "Permission required",
            Self::UnsupportedCli => "Update required",
            Self::ExistingConfigurationConflict => "Configuration conflict",
            Self::Failed => "Setup failed",
            Self::Ready { .. } => "Ready",
        }
    }

    pub(crate) const fn message(&self) -> &'static str {
        match self {
            Self::SetupRequired => {
                "Tailscale can publish AI Studio privately to your other devices. Setup is optional and never exposes the gateway directly to the Internet."
            }
            Self::Checking => "Checking Tailscale and reconciling the private Serve mapping…",
            Self::NotInstalled => {
                "Install Tailscale on this PC and your phone, sign in, then retry. GameEngine does not install external software or elevate itself."
            }
            Self::Disconnected => {
                "Open Tailscale and connect or sign in on this PC, then retry. The phone must use the same private network."
            }
            Self::AdministratorRequired => {
                "Windows denied the Serve change. GameEngine will not elevate itself; use Tailscale's own administrator-approved setup, then retry or configure another private proxy manually."
            }
            Self::UnsupportedCli => {
                "This Tailscale CLI does not provide the machine-readable status GameEngine needs to avoid changing somebody else's Serve configuration. Update Tailscale or configure manually."
            }
            Self::ExistingConfigurationConflict => {
                "HTTPS port 443 already has a Serve or Funnel configuration that GameEngine cannot prove it owns. It was left unchanged. Free that mapping yourself or configure manually."
            }
            Self::Failed => {
                "Tailscale could not publish AI Studio. GameEngine kept the raw CLI output out of the UI; retry after checking Tailscale, or configure manually."
            }
            Self::Ready { .. } => {
                "AI Studio is published through Tailscale Serve to the private tailnet. Funnel and public port forwarding are not used."
            }
        }
    }

    pub(crate) fn origin(&self) -> Option<&str> {
        match self {
            Self::Ready { origin } => Some(origin),
            _ => None,
        }
    }
}

#[derive(Debug)]
enum TailscalePublicationError {
    NotInstalled,
    Disconnected,
    AdministratorRequired,
    UnsupportedCli,
    ExistingConfigurationConflict,
    Failed,
}

impl From<TailscalePublicationError> for TailscalePublicationState {
    fn from(error: TailscalePublicationError) -> Self {
        match error {
            TailscalePublicationError::NotInstalled => Self::NotInstalled,
            TailscalePublicationError::Disconnected => Self::Disconnected,
            TailscalePublicationError::AdministratorRequired => Self::AdministratorRequired,
            TailscalePublicationError::UnsupportedCli => Self::UnsupportedCli,
            TailscalePublicationError::ExistingConfigurationConflict => {
                Self::ExistingConfigurationConflict
            }
            TailscalePublicationError::Failed => Self::Failed,
        }
    }
}

#[derive(Debug, Clone)]
struct CliOutput {
    success: bool,
    stdout: String,
    stderr: String,
}

trait TailscaleCli: Send + Sync {
    fn run(&self, arguments: &[&str]) -> io::Result<CliOutput>;
}

#[derive(Debug, Clone, Copy)]
struct SystemTailscaleCli;

impl SystemTailscaleCli {
    fn run_executable(executable: &str, arguments: &[&str]) -> io::Result<CliOutput> {
        let output = Command::new(executable).args(arguments).output()?;
        Ok(CliOutput {
            success: output.status.success(),
            stdout: String::from_utf8_lossy(&output.stdout).into_owned(),
            stderr: String::from_utf8_lossy(&output.stderr).into_owned(),
        })
    }
}

impl TailscaleCli for SystemTailscaleCli {
    fn run(&self, arguments: &[&str]) -> io::Result<CliOutput> {
        match Self::run_executable("tailscale", arguments) {
            Ok(output) => Ok(output),
            Err(error) if error.kind() == io::ErrorKind::NotFound => {
                #[cfg(windows)]
                {
                    return Self::run_executable(
                        r"C:\Program Files\Tailscale\tailscale.exe",
                        arguments,
                    );
                }
                #[cfg(not(windows))]
                {
                    Err(error)
                }
            }
            Err(error) => Err(error),
        }
    }
}

/// Background worker for one Tailscale probe/reconciliation attempt.
pub(crate) struct TailscalePublicationTask {
    receiver: mpsc::Receiver<Result<ManagedTailscalePublication, TailscalePublicationError>>,
}

impl TailscalePublicationTask {
    fn spawn(
        gateway_endpoint: String,
        previous: Option<ManagedTailscalePublication>,
    ) -> Result<Self, io::Error> {
        let (sender, receiver) = mpsc::sync_channel(1);
        thread::Builder::new()
            .name("gameengine-tailscale-publication".to_owned())
            .spawn(move || {
                let result = reconcile_tailscale(
                    &SystemTailscaleCli,
                    &gateway_endpoint,
                    previous.as_ref(),
                );
                let _ = sender.send(result);
            })?;
        Ok(Self { receiver })
    }

    fn poll(
        &self,
    ) -> Option<Result<ManagedTailscalePublication, TailscalePublicationError>> {
        match self.receiver.try_recv() {
            Ok(result) => Some(result),
            Err(mpsc::TryRecvError::Empty) => None,
            Err(mpsc::TryRecvError::Disconnected) => Some(Err(TailscalePublicationError::Failed)),
        }
    }
}

/// Machine-local controller for choosing and maintaining private publication.
pub(crate) struct RemotePublicationController {
    path: PathBuf,
    mode: RemotePublicationMode,
    managed_tailscale: Option<ManagedTailscalePublication>,
    state: TailscalePublicationState,
    task: Option<TailscalePublicationTask>,
    last_attempted_endpoint: Option<String>,
    #[cfg(feature = "visual-validation")]
    visual_fixture: bool,
}

impl RemotePublicationController {
    /// Loads machine-local publication ownership without affecting project data.
    pub(crate) fn open(path: PathBuf) -> Self {
        let persisted = fs::read(&path)
            .ok()
            .and_then(|bytes| serde_json::from_slice::<PersistedRemotePublication>(&bytes).ok())
            .filter(|state| state.schema_version == STATE_SCHEMA_VERSION)
            .unwrap_or_default();
        let state = TailscalePublicationState::SetupRequired;
        Self {
            path,
            mode: persisted.mode,
            managed_tailscale: persisted.tailscale,
            state,
            task: None,
            last_attempted_endpoint: None,
            #[cfg(feature = "visual-validation")]
            visual_fixture: false,
        }
    }

    pub(crate) const fn mode(&self) -> RemotePublicationMode {
        self.mode
    }

    pub(crate) fn state(&self) -> &TailscalePublicationState {
        &self.state
    }

    pub(crate) fn select_manual(&mut self) -> Result<(), String> {
        self.mode = RemotePublicationMode::Manual;
        self.task = None;
        self.last_attempted_endpoint = None;
        self.persist()
    }

    pub(crate) fn select_tailscale(&mut self) -> Result<(), String> {
        self.mode = RemotePublicationMode::TailscaleServe;
        self.state = TailscalePublicationState::SetupRequired;
        self.last_attempted_endpoint = None;
        self.persist()
    }

    /// Re-probes the current endpoint after an explicit Retry action.
    pub(crate) fn retry(&mut self) {
        self.last_attempted_endpoint = None;
        if self.task.is_none() {
            self.state = TailscalePublicationState::SetupRequired;
        }
    }

    /// Starts one safe reconciliation for the current dynamic gateway endpoint.
    ///
    /// A persisted Tailscale selection automatically follows a new dynamic port
    /// the next time the Remote surface is opened. A failed attempt is not
    /// repeated every frame; Retry is explicit.
    pub(crate) fn maintain(&mut self, gateway_endpoint: &str) {
        #[cfg(feature = "visual-validation")]
        if self.visual_fixture {
            return;
        }
        if self.mode != RemotePublicationMode::TailscaleServe || self.task.is_some() {
            return;
        }
        if self.last_attempted_endpoint.as_deref() == Some(gateway_endpoint) {
            return;
        }
        self.last_attempted_endpoint = Some(gateway_endpoint.to_owned());
        self.state = TailscalePublicationState::Checking;
        match TailscalePublicationTask::spawn(
            gateway_endpoint.to_owned(),
            self.managed_tailscale.clone(),
        ) {
            Ok(task) => self.task = Some(task),
            Err(_) => self.state = TailscalePublicationState::Failed,
        }
    }

    /// Applies a completed background result and persists only proven ownership.
    pub(crate) fn poll(&mut self) -> bool {
        let Some(task) = self.task.as_ref() else {
            return false;
        };
        let Some(result) = task.poll() else {
            return false;
        };
        self.task = None;
        match result {
            Ok(managed) => {
                self.state = TailscalePublicationState::Ready {
                    origin: managed.origin.clone(),
                };
                self.managed_tailscale = Some(managed);
                if self.persist().is_err() {
                    self.state = TailscalePublicationState::Failed;
                }
            }
            Err(error) => self.state = error.into(),
        }
        true
    }

    fn persist(&self) -> Result<(), String> {
        let state = PersistedRemotePublication {
            schema_version: STATE_SCHEMA_VERSION,
            mode: self.mode,
            tailscale: self.managed_tailscale.clone(),
        };
        let bytes = serde_json::to_vec_pretty(&state).map_err(|error| error.to_string())?;
        if let Some(parent) = self.path.parent() {
            fs::create_dir_all(parent).map_err(|error| error.to_string())?;
        }
        fs::write(&self.path, bytes).map_err(|error| error.to_string())
    }

    #[cfg(feature = "visual-validation")]
    pub(crate) fn prepare_visual_ready(&mut self, origin: &str) {
        self.mode = RemotePublicationMode::TailscaleServe;
        self.managed_tailscale = None;
        self.state = TailscalePublicationState::Ready {
            origin: origin.to_owned(),
        };
        self.last_attempted_endpoint = None;
        self.task = None;
        self.visual_fixture = true;
    }
}

fn reconcile_tailscale(
    cli: &dyn TailscaleCli,
    gateway_endpoint: &str,
    previous: Option<&ManagedTailscalePublication>,
) -> Result<ManagedTailscalePublication, TailscalePublicationError> {
    if !gateway_endpoint.starts_with("http://127.0.0.1:") {
        return Err(TailscalePublicationError::Failed);
    }

    let status = run_cli(cli, &["status", "--json"])?;
    let status_json: Value = serde_json::from_str(&status.stdout)
        .map_err(|_| TailscalePublicationError::UnsupportedCli)?;
    if status_json.get("BackendState").and_then(Value::as_str) != Some("Running") {
        return Err(TailscalePublicationError::Disconnected);
    }
    let dns_name = status_json
        .pointer("/Self/DNSName")
        .and_then(Value::as_str)
        .map(str::trim)
        .map(|value| value.trim_end_matches('.'))
        .filter(|value| !value.is_empty())
        .ok_or(TailscalePublicationError::UnsupportedCli)?;
    let origin = normalized_phone_url_base(&format!("https://{dns_name}"))
        .map_err(|_| TailscalePublicationError::UnsupportedCli)?;

    // Funnel status is read-only. It is checked before Serve because issuing a
    // Serve command on a Funnel-owned port would silently change public/private
    // behavior even though GameEngine never intends to configure Funnel.
    let funnel_status = run_cli(cli, &["funnel", "status", "--json"])?;
    if json_has_https_443_configuration(&parse_optional_json(&funnel_status.stdout)?) {
        return Err(TailscalePublicationError::ExistingConfigurationConflict);
    }

    let serve_status = run_cli(cli, &["serve", "status", "--json"])?;
    let serve_json = parse_optional_json(&serve_status.stdout)?;
    let existing_root = https_443_root_proxy(&serve_json);
    let any_existing_443 = json_has_https_443_configuration(&serve_json);

    match existing_root {
        Some(target)
            if previous.is_some_and(|owned| owned.gateway_endpoint() == target)
                && previous.is_some_and(|owned| owned.origin() == origin) => {}
        Some(target) if target == gateway_endpoint => {
            return Ok(ManagedTailscalePublication {
                origin,
                gateway_endpoint: gateway_endpoint.to_owned(),
            });
        }
        Some(_) => return Err(TailscalePublicationError::ExistingConfigurationConflict),
        None if any_existing_443 => {
            return Err(TailscalePublicationError::ExistingConfigurationConflict);
        }
        None => {}
    }

    run_cli(
        cli,
        &[
            "serve",
            "--bg",
            &format!("--https={TAILSCALE_HTTPS_PORT}"),
            gateway_endpoint,
        ],
    )?;

    Ok(ManagedTailscalePublication {
        origin,
        gateway_endpoint: gateway_endpoint.to_owned(),
    })
}

fn run_cli(
    cli: &dyn TailscaleCli,
    arguments: &[&str],
) -> Result<CliOutput, TailscalePublicationError> {
    match cli.run(arguments) {
        Ok(output) if output.success => Ok(output),
        Ok(output) => Err(classify_command_failure(&output.stderr)),
        Err(error) if error.kind() == io::ErrorKind::NotFound => {
            Err(TailscalePublicationError::NotInstalled)
        }
        Err(_) => Err(TailscalePublicationError::Failed),
    }
}

fn classify_command_failure(stderr: &str) -> TailscalePublicationError {
    let lowered = stderr.to_ascii_lowercase();
    if lowered.contains("administrator")
        || lowered.contains("access is denied")
        || lowered.contains("elevation")
        || lowered.contains("permission denied")
    {
        TailscalePublicationError::AdministratorRequired
    } else if lowered.contains("logged out")
        || lowered.contains("not logged in")
        || lowered.contains("not running")
        || lowered.contains("stopped")
        || lowered.contains("not connected")
    {
        TailscalePublicationError::Disconnected
    } else if lowered.contains("unknown flag") || lowered.contains("unknown command") {
        TailscalePublicationError::UnsupportedCli
    } else {
        TailscalePublicationError::Failed
    }
}

fn parse_optional_json(text: &str) -> Result<Value, TailscalePublicationError> {
    let trimmed = text.trim();
    if trimmed.is_empty() {
        return Ok(Value::Null);
    }
    serde_json::from_str(trimmed).map_err(|_| TailscalePublicationError::UnsupportedCli)
}

fn json_has_https_443_configuration(value: &Value) -> bool {
    match value {
        Value::Object(map) => map.iter().any(|(key, value)| {
            (key.contains(":443") || key == "443") && !value.is_null()
                || json_has_https_443_configuration(value)
        }),
        Value::Array(values) => values.iter().any(json_has_https_443_configuration),
        Value::String(value) => value.contains(":443"),
        _ => false,
    }
}

fn https_443_root_proxy(value: &Value) -> Option<&str> {
    let web = value.get("Web")?.as_object()?;
    for (address, site) in web {
        if !address.ends_with(":443") {
            continue;
        }
        let handler = site.get("Handlers")?.get("/")?;
        if let Some(proxy) = handler.get("Proxy").and_then(Value::as_str) {
            return Some(proxy);
        }
    }
    None
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::collections::VecDeque;
    use std::sync::Mutex;

    struct FakeCli {
        outputs: Mutex<VecDeque<io::Result<CliOutput>>>,
        calls: Mutex<Vec<Vec<String>>>,
    }

    impl FakeCli {
        fn new(outputs: Vec<io::Result<CliOutput>>) -> Self {
            Self {
                outputs: Mutex::new(outputs.into()),
                calls: Mutex::new(Vec::new()),
            }
        }

        fn ok(stdout: &str) -> io::Result<CliOutput> {
            Ok(CliOutput {
                success: true,
                stdout: stdout.to_owned(),
                stderr: String::new(),
            })
        }

        fn calls(&self) -> Vec<Vec<String>> {
            self.calls.lock().expect("calls").clone()
        }
    }

    impl TailscaleCli for FakeCli {
        fn run(&self, arguments: &[&str]) -> io::Result<CliOutput> {
            self.calls
                .lock()
                .expect("calls")
                .push(arguments.iter().map(|value| (*value).to_owned()).collect());
            self.outputs
                .lock()
                .expect("outputs")
                .pop_front()
                .expect("fake output for every command")
        }
    }

    fn running_status() -> io::Result<CliOutput> {
        FakeCli::ok(
            r#"{\"BackendState\":\"Running\",\"Self\":{\"DNSName\":\"my-pc.example-tailnet.ts.net.\"}}"#,
        )
    }

    #[test]
    fn unavailable_optional_tailscale_is_reported_without_requiring_the_executable() {
        let cli = FakeCli::new(vec![Err(io::Error::new(
            io::ErrorKind::NotFound,
            "not installed",
        ))]);
        assert!(matches!(
            reconcile_tailscale(&cli, "http://127.0.0.1:59368", None),
            Err(TailscalePublicationError::NotInstalled)
        ));
    }

    #[test]
    fn installed_but_disconnected_tailscale_is_not_ready() {
        let cli = FakeCli::new(vec![FakeCli::ok(
            r#"{\"BackendState\":\"Stopped\",\"Self\":{\"DNSName\":\"my-pc.example.ts.net.\"}}"#,
        )]);
        assert!(matches!(
            reconcile_tailscale(&cli, "http://127.0.0.1:59368", None),
            Err(TailscalePublicationError::Disconnected)
        ));
    }

    #[test]
    fn publication_success_returns_https_origin_and_current_gateway() {
        let cli = FakeCli::new(vec![
            running_status(),
            FakeCli::ok("{}"),
            FakeCli::ok("{}"),
            FakeCli::ok("Available within your tailnet"),
        ]);
        let managed = reconcile_tailscale(&cli, "http://127.0.0.1:59368", None)
            .expect("private publication");
        assert_eq!(managed.origin(), "https://my-pc.example-tailnet.ts.net");
        assert_eq!(managed.gateway_endpoint(), "http://127.0.0.1:59368");
        assert_eq!(
            cli.calls().last().expect("serve command"),
            &vec![
                "serve".to_owned(),
                "--bg".to_owned(),
                "--https=443".to_owned(),
                "http://127.0.0.1:59368".to_owned(),
            ]
        );
    }

    #[test]
    fn dynamic_gateway_port_is_reconciled_only_from_the_owned_previous_target() {
        let previous = ManagedTailscalePublication {
            origin: "https://my-pc.example-tailnet.ts.net".to_owned(),
            gateway_endpoint: "http://127.0.0.1:59368".to_owned(),
        };
        let serve = r#"{\"Web\":{\"my-pc.example-tailnet.ts.net:443\":{\"Handlers\":{\"/\":{\"Proxy\":\"http://127.0.0.1:59368\"}}}}}"#;
        let cli = FakeCli::new(vec![
            running_status(),
            FakeCli::ok("{}"),
            FakeCli::ok(serve),
            FakeCli::ok("updated"),
        ]);
        let managed = reconcile_tailscale(
            &cli,
            "http://127.0.0.1:60421",
            Some(&previous),
        )
        .expect("owned mapping can follow a new dynamic port");
        assert_eq!(managed.gateway_endpoint(), "http://127.0.0.1:60421");
        assert!(cli.calls().iter().any(|call| {
            call == &vec![
                "serve".to_owned(),
                "--bg".to_owned(),
                "--https=443".to_owned(),
                "http://127.0.0.1:60421".to_owned(),
            ]
        }));
    }

    #[test]
    fn unmanaged_existing_serve_configuration_is_never_overwritten() {
        let serve = r#"{\"Web\":{\"my-pc.example-tailnet.ts.net:443\":{\"Handlers\":{\"/\":{\"Proxy\":\"http://127.0.0.1:8000\"}}}}}"#;
        let cli = FakeCli::new(vec![
            running_status(),
            FakeCli::ok("{}"),
            FakeCli::ok(serve),
        ]);
        assert!(matches!(
            reconcile_tailscale(&cli, "http://127.0.0.1:59368", None),
            Err(TailscalePublicationError::ExistingConfigurationConflict)
        ));
        assert_eq!(cli.calls().len(), 3);
    }

    #[test]
    fn existing_funnel_configuration_blocks_publication_without_changing_it() {
        let funnel = r#"{\"Web\":{\"my-pc.example-tailnet.ts.net:443\":{\"Handlers\":{\"/\":{\"Proxy\":\"http://127.0.0.1:9000\"}}}}}"#;
        let cli = FakeCli::new(vec![running_status(), FakeCli::ok(funnel)]);
        assert!(matches!(
            reconcile_tailscale(&cli, "http://127.0.0.1:59368", None),
            Err(TailscalePublicationError::ExistingConfigurationConflict)
        ));
        assert_eq!(cli.calls().len(), 2);
        assert_eq!(
            cli.calls()[1],
            vec!["funnel", "status", "--json"],
            "Funnel is queried read-only only"
        );
    }

    #[test]
    fn no_command_can_enable_funnel_or_publish_a_non_loopback_gateway() {
        let cli = FakeCli::new(Vec::new());
        assert!(reconcile_tailscale(&cli, "http://0.0.0.0:59368", None).is_err());
        assert!(cli.calls().is_empty());

        let cli = FakeCli::new(vec![
            running_status(),
            FakeCli::ok("{}"),
            FakeCli::ok("{}"),
            FakeCli::ok("ready"),
        ]);
        reconcile_tailscale(&cli, "http://127.0.0.1:59368", None).expect("serve");
        for call in cli.calls() {
            if call.first().is_some_and(|argument| argument == "funnel") {
                assert_eq!(call, vec!["funnel", "status", "--json"]);
            }
        }
    }
}
